-- Add official SAI National Centre of Excellence (NCOE) venue records.
-- Source: SAI 53rd Governing Body meeting agenda, item 11 (official list of 23 locations):
-- https://sportsauthorityofindia.nic.in/sai_new/public/assets/uploads/documents/1740030139_67b6c0bb46bf5_agenda.pdf
-- The 2025-2026 SAI scheme brief reports 26 NCOEs, so this historical named list must not
-- be treated as proof that it exhausts the current 26. Do not invent the three unmatched names.
-- Records have only the location-level facts supported by the official list. Confirm detailed
-- street addresses, centre-specific disciplines, contacts, and admission status with SAI.

begin;

alter table public.venues
  add column if not exists source_url text,
  add column if not exists source_name text,
  add column if not exists source_checked_at timestamptz,
  add column if not exists government_facility boolean not null default false;

insert into public.venues (
  slug, name, description, city, publication_status,
  source_url, source_name, source_checked_at, government_facility
)
